function bogieSupplierFaqSchema() {
  const items = [
    ["What information does a railway bogie supplier need to quote?", "Provide the vehicle and operating duty, approved bogie and interface drawings, track gauge, axle arrangement, axle loads, speed, wheel and axle requirements, suspension, brakes, bearings and axle boxes, mounted equipment, validation status, inspection plan, documentation, quantity and delivery destination."],
    ["Is a railway bogie the same as a railway truck assembly?", "Bogie is the common term in many markets, while truck is widely used in North America. The commercial scope can still vary, so the purchase order should list every included component and whether the unit is supplied assembled, tested and ready for vehicle integration."],
    ["Can a supplier choose a standard bogie from vehicle weight alone?", "No. Vehicle mass is only one input. Compatibility also depends on axle arrangement and load, speed, track gauge and geometry, wheel and rail interfaces, suspension, braking, body connection, clearances, environmental conditions, maintenance strategy and the authorized vehicle design."],
    ["What should be included in a complete railway bogie quotation?", "The quotation should identify the controlled design baseline, included and excluded components, manufacturing and assembly scope, validation evidence, inspection and test plan, documentation, tooling, spares, packing, delivery milestones, deviations and commercial terms."],
    ["How should buyers compare freight and passenger bogie suppliers?", "Use the requirements for the actual vehicle rather than generic labels. Compare demonstrated capability for the specified duty, configuration and regulatory context, including structural and running-performance evidence, component interfaces, quality records, maintenance support and delivery scope."],
    ["Who approves a custom railway bogie design?", "The vehicle manufacturer, owner or other authorized engineering and conformity-assessment parties must define and approve the applicable design and validation route. A component supplier should not claim vehicle compatibility without the required system-level evidence and approvals."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function supplierAuditFaqSchema() {
  const items = [
    ["What should buyers audit at a railway wheel factory?", "Audit the legal and manufacturing entity, approved product scope, contract review, drawing control, material traceability, forming, heat treatment, machining, inspection, nonconformance control, subcontractors, calibration, competence, capacity, packing and release records for the exact wheel being sourced."],
    ["Is an ISO 9001 certificate enough to approve a railway wheel supplier?", "No. A valid certificate can support management-system evaluation, but it does not by itself prove capability for a specific wheel design, material, process, standard, inspection scope or delivery program. Buyers should verify certificate scope and issuer, then audit product-specific evidence."],
    ["How should buyers verify AAR approval claims?", "Where AAR requirements apply, check the current official AAR registries and technical approval information for the exact legal entity, facility, activity and scope. Do not rely only on a logo, undated PDF or another facility's certificate."],
    ["Should a railway wheel supplier disclose subcontractors?", "Critical outsourced processes and tests should be identified and controlled. The buyer should understand who performs them, which approvals and specifications apply, how the supplier qualifies and monitors the provider, and how traceability and nonconformities remain controlled."],
    ["What records should be sampled during a railway wheel supplier audit?", "Sample a completed order from contract review through material receipt, production, heat treatment, machining, inspection, marking, certificate compilation, packing and release. Match physical or recorded identifiers across each stage rather than reviewing isolated blank procedures."],
    ["How should audit findings affect supplier approval?", "Classify findings by risk and mandatory requirement, assign containment and corrective actions with owners and dates, verify objective evidence of closure, and define whether approval is rejected, conditional, limited to a scope or granted. Price should not override an unresolved safety-critical gap."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function moqLeadTimeFaqSchema() {
  const items = [
    ["What is the minimum order quantity for railway wheels?", "There is no universal railway wheel MOQ. It depends on whether the design is standard or custom, available material and tooling, manufacturing route, heat-treatment and test batch logic, machining scope, packing and the supplier's production plan. Buyers should request both the physical minimum and the commercially efficient quantity."],
    ["How long does a railway wheel order take?", "Lead time depends on when the clock starts and which milestones are included. A reliable schedule separates technical approval, tooling or first article, material, forming, heat treatment, machining, testing, document approval, packing and transport rather than giving one unsupported number."],
    ["Can a supplier reduce railway wheel MOQ for a trial order?", "Sometimes, but the supplier should explain how one-time engineering, tooling, qualification, destructive testing, setup and minimum material costs affect the trial price. Technical and inspection requirements must not be reduced merely to reach a smaller quantity."],
    ["When should railway wheel lead time start in the purchase order?", "Define an objective start event, such as receipt of the order and payment plus approval of all production-release drawings and technical documents. List buyer and supplier dependencies so delays can be assigned to the correct milestone."],
    ["How can buyers shorten railway wheel procurement lead time safely?", "Freeze the drawing and specification early, answer technical questions promptly, agree the inspection and document plan before production, verify approvals, reserve witness dates, confirm packing and shipping data, and avoid late changes. Do not shorten required manufacturing or inspection steps without authorized engineering approval."],
    ["Should spare railway wheels be ordered in one large batch?", "Not automatically. Compare demand uncertainty, storage conditions, preservation life, cash and freight economics, production continuity, fleet criticality and the cost of a stockout. A framework order or scheduled releases may be better when the supplier can preserve configuration and capacity."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function exportPackingFaqSchema() {
  const items = [
    ["How should railway wheels be packed for export?", "The packing design should suit the finished condition, mass, route, handling method and storage exposure. It normally needs stable supports, surface separation, movement restraint, corrosion protection, lifting or handling instructions, durable labels and an approved packing drawing or specification."],
    ["Do railway wheel shipments need ISPM 15 compliant wood packaging?", "When regulated raw-wood packaging or dunnage is used, the buyer and supplier should confirm the destination country's current phytosanitary requirements and use properly treated and marked material where ISPM 15 applies. Processed wood products such as plywood are outside the standard's raw-wood scope, but destination rules still need checking."],
    ["Which Incoterm should be written in a railway wheel order?", "Choose the rule that matches the agreed transport and responsibility allocation, then state the exact named port, place or point and the version, for example Incoterms 2020. The commercial parties should review the official rule rather than relying on an abbreviation alone."],
    ["What packing evidence should a railway wheel buyer request before shipment?", "Request package dimensions and weights, packing and label photographs, package identification, corrosion-protection confirmation, container or vehicle loading photographs, securing evidence where agreed, and a packing list linked to the part and certificate identifiers."],
    ["Can finished railway wheels be stacked directly together?", "Finished surfaces should not contact or move against each other unless the approved packing design specifically protects them. Separators, supports and restraints should prevent metal-to-metal damage, movement and concentrated loading during the planned transport cycle."],
    ["What information is needed to quote railway wheel packing and freight?", "Provide wheel or wheelset quantity, unit dimensions and mass, finished or semi-finished condition, corrosion-protection requirement, package limits, handling restrictions, destination, Incoterm, route and transport mode, delivery schedule and required shipping documents."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function supplierQuotationFaqSchema() {
  const items = [
    ["What should buyers compare in a railway wheel supplier quotation?", "Compare compliance with the same drawing revision, standard edition, material and supply condition; then compare inspection scope, documentation, tooling, packing, delivery, commercial terms, exclusions and total landed cost."],
    ["Is the lowest railway wheel unit price usually the best offer?", "Not necessarily. A lower unit price may exclude finish machining, testing, inspection records, export packing, tooling, freight or other required work. Normalize every quotation to the same technical and commercial scope before ranking it."],
    ["How can buyers make railway wheel quotations comparable?", "Issue one controlled RFQ package and require suppliers to return a compliance matrix, deviation list and itemized price schedule. Record clarifications in writing and revise the comparison only after each offer uses the same baseline."],
    ["Which inspection documents should be priced in the quotation?", "The contract should identify required material certificates, mechanical and heat-treatment results, dimensional records, specified non-destructive examination, marking and traceability evidence, and any third-party inspection or witness points."],
    ["Should a supplier propose an alternative railway wheel standard or material?", "A supplier may identify an alternative, but it must be clearly marked as a deviation. The buyer's authorized engineering function must review and approve any substitution before it becomes part of the order."],
    ["What information helps a railway wheel supplier quote accurately?", "Provide the controlled drawing and revision, application, governing standard and edition, material, machining condition, quantity, inspection plan, documentation, packing, destination, delivery terms and required schedule."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function replacementWheelDimensionsFaqSchema() {
  const items = [
    ["Which dimensions are needed to quote a replacement railway wheel?", "Use the controlled wheel drawing and identify its revision. The quotation package normally needs the finished and any supply diameters, bore and hub geometry, rim and web geometry, complete tread and flange profile, datums, tolerances, surface finish, marking and the axle or wheelset interfaces relevant to the ordered scope."],
    ["Is nominal wheel diameter enough for a replacement wheel quotation?", "No. Wheels with the same nominal diameter can differ in tread profile, bore, hub, rim, web, material, machining condition and interfaces. A nominal diameter plus photographs is not a controlled replacement definition."],
    ["Can a worn railway wheel be used as the only dimensional reference?", "A worn sample can support identification and condition review, but it should not become the sole design authority for a safety-critical replacement. Wear, previous machining, damage and measurement uncertainty can conceal the approved new-wheel geometry."],
    ["Should the RFQ state new-wheel and service-limit dimensions?", "State the new-part acceptance dimensions required for supply. Service and condemnation limits belong to the operator's authorized maintenance documentation and should only be included when they are necessary to define an approved maintenance or machining scope."],
    ["Does EN 13715 define every dimension needed to purchase a railway wheel?", "No. EN 13715 addresses wheel tread profiles. A purchase definition still needs the approved wheel drawing, product and material requirements, interfaces, tolerances, inspection plan and project-specific acceptance criteria."],
    ["What should a supplier do when the drawing and standard conflict?", "The supplier should raise a technical clarification before manufacture. The purchase specification should state document precedence, and the purchaser's authorized engineering function should approve any resolution or deviation in writing."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function wheelReplacementFaqSchema() {
  const items = [
    ["When should a railway wheel be replaced instead of reprofiled?", "The authorized maintenance plan and responsible engineering authority must make that decision. Replacement may be required when approved dimensional or defect limits would not be met after machining, when a non-repairable condition is found, or when remaining life no longer supports the maintenance plan."],
    ["Can a supplier quote a replacement railway wheel from diameter alone?", "No. A reliable RFQ also needs the controlled drawing or approved specification, wheel and axle interfaces, material and standard, vehicle duty, quantity, inspection documents, marking, packing and destination."],
    ["Does reprofiling restore a wheel to new condition?", "No. Reprofiling restores an approved tread profile by removing material. It does not reverse material loss, erase every defect or replace the inspections and acceptance criteria required by the maintenance plan."],
    ["Which standard covers in-service wheelset maintenance in European practice?", "EN 15313:2024 addresses in-service operation requirements and in-service and off-vehicle wheelset maintenance. Project-specific values and decision criteria still belong in the authorized maintenance plan."],
    ["What should be included in a railway wheel replacement quotation?", "The quotation should identify the drawing revision, standard edition, material grade, supply condition, inspection and documentation scope, marking, packing, quantity, delivery basis, exclusions and any technical clarifications."],
    ["Should both wheels on an axle be replaced together?", "Do not apply a universal rule. The authorized maintenance plan, wheelset design, applicable rules and responsible engineering authority must define the permitted work scope and final wheelset acceptance criteria."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

function inspectionDocumentsFaqSchema() {
  const items = [
    ["Which inspection documents should a railway wheel buyer request?", "The contract should define the exact package. It may include a material inspection certificate, heat-treatment and mechanical-test results, NDT reports, hardness and dimensional records, marking evidence, a certificate of conformity and a document index."],
    ["Does an EN 10204 3.1 certificate prove that a railway wheel meets every project requirement?", "No. An EN 10204 inspection certificate reports conformity and specified test results within its defined scope. Buyers must still review the wheel standard, drawing, inspection plan, traceability and all other contract requirements."],
    ["Should every railway wheel have an ultrasonic test report?", "Only when the governing standard, drawing or purchase specification requires it. The requirement must define the procedure, coverage, acceptance level, reporting and traceability before production."],
    ["How can buyers check railway wheel traceability?", "Match the physical marking or approved identifier to the material certificate, heat-treatment batch, test reports, dimensional record, release document and packing list. Resolve missing or conflicting identifiers before shipment."],
    ["When should the document package be agreed?", "Agree the document schedule, formats, language, review points and release conditions during the RFQ and before order placement. Adding requirements after production can affect cost and schedule."]
  ];
  return { "@context": "https://schema.org", "@type": "FAQPage", "mainEntity": items.map(([question, answer]) => ({ "@type": "Question", "name": question, "acceptedAnswer": { "@type": "Answer", "text": answer } })) };
}

